// One place for everything tunable.
//
// Three sources feed one pipeline. They are deliberately independent: each
// branch has neverError set, so a source that is down, rate-limited or has
// changed its schema produces zero rows instead of killing the run. A day
// with two sources is a smaller day, not a failed one. That is the whole
// reason for using more than one.
return [{ json: {
  campaignId: 'df17f3eb-368d-415f-99ab-b6a7325dad3c',

  // --- G2: narrow categories only -------------------------------------
  // A buyer token returns a category's TOP products. In a broad category
  // those are the giants; in a narrow one they are the whole category.
  // Measured: ~1.6 usable prospects per narrow category, 0 per broad one.
  g2Categories: [
    'ai-sales-roleplay-tools','ai-proposal-generator-tools','event-lead-capture',
    'ai-interview-agent','ai-documentation-generators','site-search-software',
    'ai-sre-tools','website-privacy-auditing-tools','ai-agent-observability',
    'semantic-layer-tools','virtual-recording-studio','low-code-mobile-app-builder'
  ],
  g2MinReviews: 10,
  g2MaxReviews: 250,

  // --- Product Hunt: recent launches, enough votes to be real ----------
  // Launch date is a better recency signal than a review count: it finds
  // companies while they are still small, which is the band we want and
  // the band G2 is slowest to list.
  phMinVotes: 30,
  phMaxVotes: 1200,
  phMaxAgeDays: 400,

  // --- Hacker News: Show HN, free and unauthenticated ------------------
  hnMinPoints: 20,

  // Competitors, and companies selling the outcome we sell.
  excludeDomains: [
    'linkfinderai.com','clay.com','warmly.ai','6sense.com','apollo.io',
    'zoominfo.com','lusha.com','cognism.com','hunter.io','snov.io',
    'rocketreach.co','seamless.ai','uplead.com','findymail.com',
    'dropcontact.com','kaspr.io','surfe.com','prospeo.io','anymailfinder.com',
    'tryprofound.com','peec.ai','otterly.ai','athenahq.ai','scrunchai.com',
    'goodie.ai','brandlight.ai'
  ],

  // Domains that are never a company: aggregators, hosts, social.
  excludeHosts: [
    'producthunt.com','github.com','gitlab.com','medium.com','substack.com',
    'notion.so','notion.site','youtube.com','twitter.com','x.com','apple.com',
    'play.google.com','chromewebstore.google.com','news.ycombinator.com',
    'reddit.com','linkedin.com','vercel.app','netlify.app','herokuapp.com',
    'streamlit.app','replit.app','glitch.me','pages.dev','webflow.io'
  ]
} }];

// Refuse to spend a credit we cannot use.
//
// Learned the expensive way: the workspace sat 6,089 leads over its cap,
// so every upload would have 403'd -- but only AFTER LinkFinder had been
// paid for each enrichment.
const cfg = $('Config').first().json;
const plan = $input.first().json;
const sub = plan?.subscriptions?.outreach || plan || {};
const limit = sub.total_lead_limit, used = sub.current_lead_count;

if (limit == null || used == null) {
  return [{ json: { ...cfg, room: 25, note: 'lead limit unreadable; capped at 25' } }];
}
const room = limit - used;
if (room <= 0) {
  throw new Error(`Instantly has no room: ${used}/${limit}, ${-room} over the cap. `
    + `Free space first, or you pay to enrich leads that cannot be uploaded.`);
}
return [{ json: { ...cfg, room } }];

// Product Hunt -> the common shape.
//
// The `website` field is often a producthunt.com redirect rather than the
// product's own domain, and it usually carries ref/utm junk. Both have to
// go: a redirect host is not a company, and a tracking query string breaks
// domain matching downstream.
const cfg = $('Stop if no room').first().json;
const body = $input.first().json;
const payload = body?.body ?? body;
const edges = payload?.data?.posts?.edges || [];
const now = Date.now();
const out = [];

for (const e of edges) {
  const n = e?.node; if (!n) continue;

  let host = '';
  try { host = new URL(n.website || '').hostname.toLowerCase().replace(/^www\./, ''); }
  catch { continue; }
  if (!host) continue;

  // A producthunt.com/r/... redirect means the real domain is not exposed
  // here. Skip rather than mail Product Hunt.
  if (cfg.excludeHosts.some(h => host === h || host.endsWith('.' + h))) continue;
  if (cfg.excludeDomains.includes(host)) continue;

  const votes = n.votesCount || 0;
  if (votes < cfg.phMinVotes || votes > cfg.phMaxVotes) continue;

  const ageDays = (now - new Date(n.createdAt).getTime()) / 86400000;
  if (!isFinite(ageDays) || ageDays > cfg.phMaxAgeDays) continue;

  const topic = n.topics?.edges?.[0]?.node?.name || '';

  out.push({ json: {
    source: 'producthunt',
    domain: host,
    company: n.name || host,
    category: topic || 'software',
    signal: 'upvotes',
    signalValue: votes,
    campaignId: cfg.campaignId
  }});
}
return out;

// G2 -> the common shape.
//
// The review band is the qualifier: below it a stub listing, above it a
// category leader with an SEO team who does not need us.
const cfg = $('Stop if no room').first().json;
const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const categoryName = body?.data?.attributes?.name || item.json.slug || 'software';
  const products = (body?.included || [])
    .filter(i => i.type === 'products' && i.attributes?.domain)
    .map(i => ({
      domain: String(i.attributes.domain).trim().toLowerCase().replace(/^www\./, ''),
      company: i.attributes.name || '',
      reviews: i.attributes.review_count || 0
    }));
  if (!products.length) continue;

  // No reachable tail in this category -- every visible row is a giant.
  if (Math.min(...products.map(p => p.reviews)) > cfg.g2MaxReviews) continue;

  for (const p of products) {
    if (cfg.excludeDomains.includes(p.domain)) continue;
    if (cfg.excludeHosts.some(h => p.domain === h || p.domain.endsWith('.' + h))) continue;
    if (p.reviews < cfg.g2MinReviews || p.reviews > cfg.g2MaxReviews) continue;
    out.push({ json: {
      source: 'g2', domain: p.domain, company: p.company,
      category: categoryName, signal: 'reviews', signalValue: p.reviews,
      campaignId: cfg.campaignId
    }});
  }
}
return out;

// Hacker News -> the common shape.
//
// Free and unauthenticated, so it costs nothing to keep even when the yield
// is low. Show HN skews developer-tools, which suits an offer sold on being
// found in AI answers.
const cfg = $('Stop if no room').first().json;
const body = $input.first().json;
const payload = body?.body ?? body;
const hits = payload?.hits || [];
const out = [];

for (const h of hits) {
  if ((h.points || 0) < cfg.hnMinPoints) continue;
  let host = '';
  try { host = new URL(h.url || '').hostname.toLowerCase().replace(/^www\./, ''); }
  catch { continue; }
  if (!host) continue;
  if (cfg.excludeHosts.some(x => host === x || host.endsWith('.' + x))) continue;
  if (cfg.excludeDomains.includes(host)) continue;

  // "Show HN: Acme – does a thing" -> "Acme"
  const title = String(h.title || '');
  const company = (title.replace(/^show hn:?\s*/i, '').split(/[\u2013\u2014\-:|,]/)[0] || host).trim();

  out.push({ json: {
    source: 'hackernews', domain: host, company: company || host,
    category: 'software', signal: 'hn points', signalValue: h.points || 0,
    campaignId: cfg.campaignId
  }});
}
return out;

// One company, one email, ever.
//
// Three sources will absolutely surface the same company twice -- a product
// on G2 that also launched on Product Hunt is the normal case, not the edge
// case. Mailing it twice from two branches is the fastest way to look like
// a bot.
//
// When the same domain arrives twice, keep the row with the most specific
// category: G2 gives a real category name, Product Hunt gives a topic, and
// HN gives 'software'. The category is a merge field in the opener, so the
// specific one is worth keeping.
const cfg = $('Stop if no room').first().json;
const rank = { g2: 3, producthunt: 2, hackernews: 1 };
const best = new Map();

for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.domain) continue;
  const prev = best.get(r.domain);
  if (!prev || (rank[r.source] || 0) > (rank[prev.source] || 0)) best.set(r.domain, r);
}

let rows = [...best.values()];

// Never enrich more than we can upload.
if (cfg.room && cfg.room > 0) rows = rows.slice(0, cfg.room);

return rows.map(json => ({ json }));

// A failure that no HTTP status code describes.
//
// This endpoint answers 200 / "success" even when its upstream is down,
// putting a status message where a person should be:
//   {"personId": null, "name": "We are on maintenance. Check back in 48hrs"}
// Measured across ~20 live calls: roughly HALF, interleaved with good
// answers for similar domains seconds apart. One sentinel means retry.
//
// ORDER MATTERS. Look for a real person FIRST and only ask why we failed
// when we actually failed. The actor also injects a chatty banner row
// alongside genuine results, so checking sentinels first throws away a good
// lead and pays to look it up again. Real data always wins.
const OUTAGE = ['maintenance','check back in','we improve the actor','contact us if you are having'];
const prospect = $('One prospect at a time').first().json;
const body = $input.first().json;
const payload = body?.body ?? body;
let rows = payload?.result ?? payload?.employees ?? payload;
while (rows && !Array.isArray(rows) && rows.result) rows = rows.result;
if (!Array.isArray(rows)) rows = [];

const person = rows.find(r => r && (r.personId || r.person_id) &&
  r.email && String(r.email).includes('@') && r.name);

if (person) {
  const parts = String(person.name).trim().split(/\s+/);
  return [{ json: { ...prospect, status: 'ok', email: person.email.trim(),
    firstName: parts[0], lastName: parts.slice(1).join(' '),
    title: person.jobTitle || person.job_title || '' } }];
}

const sentinel = rows.find(r => r && !r.personId && !r.person_id &&
  OUTAGE.some(m => String(r.name || '').toLowerCase().includes(m)));

if (sentinel) return [{ json: { ...prospect, status: 'provider_down', reason: sentinel.name } }];
return [{ json: { ...prospect, status: 'no_person' } }];
